import { db } from './client';
import type { OrderWithCustomer } from './types';

export async function listOrders(opts: { from?: Date; to?: Date; limit?: number }): Promise<OrderWithCustomer[]> {
  const orders = await db.order.findMany({
    where: { createdAt: { gte: opts.from, lt: opts.to } },
    include: { customer: true },
    orderBy: { createdAt: 'desc' },
    take: opts.limit,
  });
  return orders.map(o => ({ ...o, subtotal: o.subtotal.toNumber(), total: o.total.toNumber() })) as OrderWithCustomer[];
}

